fn count_vowels(text: Text) -> Number {
    let vowels = ["a","e","i","o","u"]
    var count = 0
    for ch in text.lower().chars() {
        if vowels.contains(ch) {
            count = count + 1
        }
    }
    return count
}

test "the ask's own tests" {
  expect count_vowels("banana") == 3
  expect count_vowels("") == 0
  expect count_vowels("Apple") == 2
  expect count_vowels("aeiouAEIOU") == 10
}

