fn reverseWords(sentence: Text) -> Text {
    if sentence == "" {
        return ""
    }
    var words = sentence.split(" ")
    var nonEmptyWords: Text[] = []
    for w in words {
        if w != "" {
            nonEmptyWords.append(w)
        }
    }
    var result = ""
    for w in nonEmptyWords {
        if result == "" {
            result = w
        } else {
            result = w + " " + result
        }
    }
    return result
}

test "reverseWords basic and edge cases" {
  expect reverseWords("hello world") == "world hello"
  expect reverseWords("a b c d") == "d c b a"
  expect reverseWords("") == ""
  expect reverseWords("single") == "single"
  expect reverseWords("  leading and trailing  ") == "trailing and leading"
}

fn reverseWords(sentence: Text) -> Text {
  var parts = sentence.split(" ")
  var words: Text[] = []
  for p in parts {
    if p != "" {
      words.append(p)
    }
  }
  var result = ""
  var i = words.length() - 1
  while i >= 0 {
    var w = words[i]
    if result == "" {
      result = w
    } else {
      result = w + " " + result
    }
    i = i - 1
  }
  return result
}

test "reverseWords tests" {
  expect reverseWords("hello world") == "world hello"
  expect reverseWords("  hello   world  ") == "world hello"
  expect reverseWords("single") == "single"
  expect reverseWords("") == ""
  expect reverseWords("a b c") == "c b a"
}

fn fizzbuzz(n: Number) -> Text {
    if n % 3 == 0 and n % 5 == 0 {
        return "FizzBuzz"
    }
    if n % 3 == 0 {
        return "Fizz"
    }
    if n % 5 == 0 {
        return "Buzz"
    }
    return n.to_text()
}

test "fizzbuzz function" {
  expect fizzbuzz(1) == "1"
  expect fizzbuzz(3) == "Fizz"
  expect fizzbuzz(5) == "Buzz"
  expect fizzbuzz(15) == "FizzBuzz"
  expect fizzbuzz(16) == "16"
}

fn is_prime(n: Number) -> Bool {
    if n < 2 { return false }
    var i = 2
    while i * i <= n {
        if n % i == 0 { return false }
        i = i + 1
    }
    return true
}

test "prime tests" {
  expect is_prime(2) == true
  expect is_prime(3) == true
  expect is_prime(4) == false
  expect is_prime(5) == true
  expect is_prime(9) == false
}

fn max_or_zero(nums: List<Number>) -> Number {
    if nums.length() == 0 {
        return 0
    }
    var max = nums[0]
    for n in nums {
        if n > max {
            max = n
        }
    }
    return max
}

test "max_or_zero's own tests" {
  expect max_or_zero([1, 3, 2, 5, 4]) == 5
  expect max_or_zero([]) == 0
  expect max_or_zero([10]) == 10
  expect max_or_zero([-1, -3, -2]) == -1
  expect max_or_zero([0, 0, 0]) == 0
  expect max_or_zero([2, 2, 2, 3]) == 3
}

